import{_ as t,o as i,c as r,ae as o}from"./chunks/framework.Czhw_PXq.js";const g=JSON.parse('{"title":"📊 Metrics & Coverage Policy - TenderCheck AI","description":"","frontmatter":{},"headers":[],"relativePath":"standards/metrics_policy.md","filePath":"standards/metrics_policy.md"}'),a={name:"standards/metrics_policy.md"};function s(c,e,l,n,d,u){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="📊-metrics-coverage-policy-tendercheck-ai" tabindex="-1">📊 Metrics &amp; Coverage Policy - TenderCheck AI <a class="header-anchor" href="#📊-metrics-coverage-policy-tendercheck-ai" aria-label="Permalink to &quot;📊 Metrics &amp; Coverage Policy - TenderCheck AI&quot;">​</a></h1><h2 id="_1-code-coverage-policy-the-honest-coverage-100-80-0" tabindex="-1">1. Code Coverage Policy (The &quot;Honest Coverage&quot; 100/80/0) <a class="header-anchor" href="#_1-code-coverage-policy-the-honest-coverage-100-80-0" aria-label="Permalink to &quot;1. Code Coverage Policy (The &quot;Honest Coverage&quot; 100/80/0)&quot;">​</a></h2><p>[cite_start]To ensure reliability, we follow a tiered coverage strategy[cite: 198]:</p><ul><li><strong>CORE (src/domain &amp; critical helpers)</strong>: <strong>100% coverage</strong> enforced. [cite_start]Every business rule must be tested[cite: 199].</li><li>[cite_start]<strong>GLOBAL (Application &amp; UI logic)</strong>: <strong>80% minimum coverage</strong>[cite: 200, 657, 690].</li><li>[cite_start]<strong>INFRA (Config &amp; Setup)</strong>: <strong>0% coverage</strong> (excluded from metrics to avoid &quot;noise&quot;)[cite: 201].</li></ul><h2 id="_2-technical-quality-metrics" tabindex="-1">2. Technical Quality Metrics <a class="header-anchor" href="#_2-technical-quality-metrics" aria-label="Permalink to &quot;2. Technical Quality Metrics&quot;">​</a></h2><p>[cite_start]We implement automatic quality controls to monitor code health[cite: 655, 689]:</p><ul><li>[cite_start]<strong>Cyclomatic Complexity</strong>: We monitor complexity to ensure functions remain simple and testable[cite: 656, 718].</li><li><strong>Maintainability Index</strong>: Aim for high scores by avoiding &quot;God Objects&quot; and long functions.</li><li><strong>Cognitive Complexity</strong>: Code must be easy for a human to read, not just for the compiler.</li></ul><h2 id="_3-quality-gates-enforcement" tabindex="-1">3. Quality Gates &amp; Enforcement <a class="header-anchor" href="#_3-quality-gates-enforcement" aria-label="Permalink to &quot;3. Quality Gates &amp; Enforcement&quot;">​</a></h2><ul><li>[cite_start]<strong>Husky &amp; Git Hooks</strong>: A pre-push hook will block any commit that fails to meet the 80% coverage threshold or has failing tests[cite: 202, 657, 719].</li><li>[cite_start]<strong>GitHub Actions</strong>: Our CI pipeline will audit code quality on every Pull Request, ensuring deficiente code never reaches production[cite: 657, 690, 723].</li></ul><h2 id="_4-observability-real-world-metrics" tabindex="-1">4. Observability &amp; Real-world Metrics <a class="header-anchor" href="#_4-observability-real-world-metrics" aria-label="Permalink to &quot;4. Observability &amp; Real-world Metrics&quot;">​</a></h2><p>[cite_start]Beyond testing, we complement quality with observability[cite: 664]:</p><ul><li>[cite_start]<strong>Performance Monitoring</strong>: Track &quot;perceived speed&quot; and Core Web Vitals[cite: 664, 682].</li><li>[cite_start]<strong>Error Tracking (Sentry)</strong>: Implement real-time alerts for production errors and performance degradation[cite: 664, 665].</li><li>[cite_start]<strong>AI Audit Logs</strong>: Every decision source (Rule vs AI) must be logged to ensure system transparency[cite: 1073].</li></ul>',12)])])}const h=t(a,[["render",s]]);export{g as __pageData,h as default};
